    SELECT m.id FROM moves m JOIN characters c ON c.id = m.character_id WHERE c.code = 'zangief' AND c.game_id IN (SELECT id FROM games WHERE code = 'sf6') AND m.code IN ('borscht_dynamite', 'borscht_dynamite_od', 'brain_buster', 'ca_bolshoi_storm_buster', 'crouching_heavy_kick', 'crouching_light_kick', 'crouching_light_punch', 'crouching_medium_kick', 'crouching_medium_punch', 'cyclone_wheel_kick', 'double_lariat', 'double_lariat_od', 'drive_impact', 'drive_parry', 'flying_headbutt', 'german_suplex', 'headbutt', 'hellstab', 'jumping_heavy_kick', 'jumping_heavy_kick_holding', 'jumping_heavy_punch', 'jumping_light_kick', 'jumping_light_punch', 'jumping_medium_kick', 'jumping_medium_punch', 'knee_hammer', 'machine_gun_chops', 'machine_gun_chops_2hits', 'power_stomps', 'power_stomps_1hits', 'power_stomps_2hits', 'rush_crouching_heavy_kick', 'rush_crouching_light_kick', 'rush_crouching_light_punch', 'rush_crouching_medium_kick', 'rush_crouching_medium_punch', 'rush_cyclone_wheel_kick', 'rush_headbutt', 'rush_hellstab', 'rush_knee_hammer', 'rush_power_stomps_1hits', 'rush_smetana_dropkick', 'rush_standing_heavy_kick', 'rush_standing_heavy_punch', 'rush_standing_heavy_punch_holding', 'rush_standing_light_kick', 'rush_standing_light_punch', 'rush_standing_medium_kick', 'rush_standing_medium_punch', 'russian_drop', 'sa1_aerial_russian_slam', 'sa2_cyclone_lariat_forward', 'sa3_bolshoi_storm_buster', 'screw_piledriver_heavy', 'screw_piledriver_light', 'screw_piledriver_medium', 'screw_piledriver_od', 'smetana_dropkick', 'spinebuster', 'standing_heavy_kick', 'standing_heavy_punch', 'standing_heavy_punch_holding', 'standing_light_kick', 'standing_light_punch', 'standing_medium_kick', 'standing_medium_punch', 'throw_back', 'throw_forward', 'tundra_storm'));

