-- ===== 層 C-1: 移動系(19 キャラ) =====
DELETE FROM preset_aliases WHERE preset_id = (SELECT id FROM presets WHERE code = 'numeric') AND move_id IN (
    SELECT m.id FROM moves m
    JOIN characters c ON c.id = m.character_id
    JOIN games g ON g.id = c.game_id AND g.code = 'sf6'
    WHERE c.code IN ('c_viper', 'dhalsim', 'guile', 'ingrid', 'jamie', 'jp', 'juri', 'ken', 'kimberly', 'lily', 'luke', 'm_bison', 'mai', 'manon', 'marisa', 'rashid', 'ryu', 'terry', 'zangief') AND m.category = 'system' AND m.code IN ('forward', 'back', 'dash_forward', 'dash_back', 'jump_neutral', 'jump_forward', 'jump_back', 'micro_forward', 'micro_back'));

